window.PROBLEMS=[{"id":"q1","tier":"easy","topic":"aggregation","title":"Policies per product","prompt":"The underwriting team wants a quick count of how many policies exist for each product line. Using the policies table, return product and n (policy count), highest count first, ties broken by product.","hint":"GROUP BY product, then ORDER BY the count.","solution":"SELECT product, COUNT(*) AS n\nFROM policies\nGROUP BY product\nORDER BY n DESC, product;","explanation":"Basic GROUP BY. The tie-break on product makes the order deterministic.","ordered":true,"similar":null,"columns":["product","n"],"expected":["Auto␟7.00","GL␟7.00","WC␟5.00","BOP␟4.00"],"tables":["policies"]},{"id":"q2","tier":"easy","topic":"aggregation","title":"Written premium by state","prompt":"Using the policies table, return each state and total_premium (sum of premium, rounded to 2 decimals), sorted by state.","hint":"SUM then ROUND(x, 2). premium is NUMERIC so ROUND works directly.","solution":"SELECT state, ROUND(SUM(premium), 2) AS total_premium\nFROM policies\nGROUP BY state\nORDER BY state;","explanation":"Aggregate, then round. In Postgres ROUND(value, digits) needs NUMERIC; ROUND(double precision, int) does not exist, so cast with ::numeric when needed.","ordered":true,"similar":null,"columns":["state","total_premium"],"expected":["CA␟19404.34","FL␟5750.89","NY␟6675.26","TX␟5424.67"],"tables":["policies"]},{"id":"q3","tier":"easy","topic":"filtering","title":"Open claims with large reserves","prompt":"Claims ops wants every OPEN claim whose reserve_amount is above 3000. From the claims table, return claim_id and reserve_amount ordered by claim_id.","hint":"Two conditions joined with AND.","solution":"SELECT claim_id, reserve_amount\nFROM claims\nWHERE status = 'OPEN' AND reserve_amount > 3000\nORDER BY claim_id;","explanation":"Straight filter. String comparison is case-sensitive in Postgres (use ILIKE or lower() for case-insensitive).","ordered":true,"similar":null,"columns":["claim_id","reserve_amount"],"expected":["2.00␟5251.91","9.00␟5915.67","11.00␟3875.55","12.00␟5755.07","13.00␟5962.06","14.00␟4623.21","15.00␟5736.12","19.00␟4569.30","21.00␟5760.83","22.00␟3085.44"],"tables":["claims"]},{"id":"q4","tier":"easy","topic":"joins","title":"Claims with their product","prompt":"Tables: claims, policies. For each claim show claim_id, the product of the policy it was filed against, and paid_amount. Order by claim_id.","hint":"claims.policy_id references policies.policy_id.","solution":"SELECT c.claim_id, p.product, c.paid_amount\nFROM claims c\nJOIN policies p ON p.policy_id = c.policy_id\nORDER BY c.claim_id;","explanation":"INNER JOIN on the foreign key.","ordered":true,"similar":null,"columns":["claim_id","product","paid_amount"],"expected":["1.00␟GL␟909.12","2.00␟GL␟7409.66","3.00␟GL␟7980.90","4.00␟GL␟2241.22","5.00␟BOP␟236.02","6.00␟BOP␟3003.78","7.00␟GL␟6150.56","8.00␟GL␟3711.01","9.00␟WC␟1877.36","10.00␟GL␟662.67","11.00␟BOP␟8550.75","12.00␟GL␟5782.80","13.00␟Auto␟7670.64","14.00␟WC␟1468.23","15.00␟WC␟2005.89","16.00␟GL␟2823.19","17.00␟GL␟8192.68","18.00␟WC␟3101.05","19.00␟Auto␟7401.33","20.00␟GL␟6632.84","21.00␟WC␟6294.19","22.00␟Auto␟1098.98","23.00␟WC␟1500.00","24.00␟WC␟0.00"],"tables":["claims","policies"]},{"id":"q5","tier":"easy","topic":"joins","title":"Customers who never filed a claim","prompt":"Tables: customers, policies, claims. Return the name of every customer who has never had a claim on any of their policies. Order by name.","hint":"Anti-join: NOT EXISTS (policies joined to claims for that customer).","solution":"SELECT cu.name\nFROM customers cu\nWHERE NOT EXISTS (\n  SELECT 1 FROM policies p\n  JOIN claims c ON c.policy_id = p.policy_id\n  WHERE p.customer_id = cu.customer_id)\nORDER BY cu.name;","explanation":"Anti-join. NOT EXISTS is NULL-safe; NOT IN silently returns nothing if the subquery yields a NULL.","ordered":true,"similar":{"url":"https://leetcode.com/problems/customers-who-never-order/","title":"LeetCode: Customers Who Never Order"},"columns":["name"],"expected":["Ben","Cara","Fay"],"tables":["claims","customers","policies"]},{"id":"q6","tier":"easy","topic":"aggregation","title":"Average severity by cause","prompt":"From claims, compute avg_incurred per cause, where incurred = paid_amount + reserve_amount, rounded to 2 decimals. Sort by avg_incurred descending.","hint":"AVG(paid_amount + reserve_amount).","solution":"SELECT cause, ROUND(AVG(paid_amount + reserve_amount), 2) AS avg_incurred\nFROM claims\nGROUP BY cause\nORDER BY avg_incurred DESC;","explanation":"Severity = average loss per claim.","ordered":true,"similar":null,"columns":["cause","avg_incurred"],"expected":["Collision␟11537.87","Theft␟7774.42","Fire␟6514.09","Injury␟6441.74","Water␟4425.82"],"tables":["claims"]},{"id":"q7","tier":"easy","topic":"having","title":"States with 3+ customers","prompt":"From customers, return state and n for states that have at least 3 customers. Order by state.","hint":"HAVING filters groups after aggregation.","solution":"SELECT state, COUNT(*) AS n\nFROM customers\nGROUP BY state\nHAVING COUNT(*) >= 3\nORDER BY state;","explanation":"WHERE filters rows before grouping; HAVING filters groups after.","ordered":true,"similar":null,"columns":["state","n"],"expected":["CA␟4.00","NY␟3.00","TX␟3.00"],"tables":["customers"]},{"id":"q8","tier":"easy","topic":"dates","title":"Claims reported within a week","prompt":"From claims, return claim_id and lag_days (report_date - loss_date) for claims reported within 7 days of the loss. Order by claim_id.","hint":"In Postgres, DATE - DATE returns an integer number of days.","solution":"SELECT claim_id, report_date - loss_date AS lag_days\nFROM claims\nWHERE report_date - loss_date <= 7\nORDER BY claim_id;","explanation":"date - date = integer days. timestamp - timestamp = INTERVAL (use EXTRACT(EPOCH FROM ...) or ::date). Databricks uses datediff(end, start).","ordered":true,"similar":null,"columns":["claim_id","lag_days"],"expected":["2.00␟2.00","3.00␟2.00","4.00␟1.00","5.00␟2.00","8.00␟5.00","9.00␟5.00","10.00␟2.00","12.00␟5.00","13.00␟0.00","14.00␟2.00","16.00␟0.00","20.00␟5.00","21.00␟2.00","22.00␟0.00","23.00␟1.00","24.00␟0.00"],"tables":["claims"]},{"id":"q9","tier":"easy","topic":"dates","title":"Quotes per month","prompt":"From quotes, return month (first day of the month, as a date) and quotes (count). Order by month.","hint":"DATE_TRUNC('month', d) returns a timestamp; cast with ::date.","solution":"SELECT DATE_TRUNC('month', quote_date)::date AS month, COUNT(*) AS quotes\nFROM quotes\nGROUP BY 1\nORDER BY 1;","explanation":"DATE_TRUNC is the standard month bucket in Postgres, Databricks and Snowflake. Keeping it a date (not a 'YYYY-MM' string) keeps sorting and joining easy.","ordered":true,"similar":null,"columns":["month","quotes"],"expected":["2024-01-01␟2.00","2024-02-01␟1.00","2024-03-01␟4.00","2024-04-01␟1.00","2024-07-01␟2.00","2024-08-01␟2.00","2024-09-01␟1.00","2024-10-01␟1.00","2024-12-01␟1.00","2025-01-01␟1.00","2025-02-01␟1.00","2025-03-01␟1.00","2025-04-01␟1.00","2025-05-01␟4.00","2025-08-01␟1.00","2025-09-01␟2.00","2026-01-01␟3.00","2026-03-01␟1.00"],"tables":["quotes"]},{"id":"q10","tier":"easy","topic":"case","title":"Bind rate by product","prompt":"From quotes (bound is BOOLEAN), return product and bind_rate_pct = % of quotes bound, 1 decimal. Order by product.","hint":"COUNT(*) FILTER (WHERE bound) / COUNT(*), or AVG(bound::int).","solution":"SELECT product,\n  ROUND(100.0 * COUNT(*) FILTER (WHERE bound) / COUNT(*), 1) AS bind_rate_pct\nFROM quotes\nGROUP BY product\nORDER BY product;","explanation":"FILTER (WHERE ...) is Postgres's clean conditional aggregate. 100.0 forces numeric division (int/int truncates in Postgres).","ordered":true,"similar":null,"columns":["product","bind_rate_pct"],"expected":["Auto␟40.00","BOP␟0.00","GL␟11.10","WC␟27.30"],"tables":["quotes"]},{"id":"q11","tier":"easy","topic":"case","title":"Premium buckets","prompt":"From policies, count policies per bucket: '<1000', '1000-2499', '2500+'. Return bucket and n ordered by bucket.","hint":"CASE WHEN ... END, then GROUP BY 1.","solution":"SELECT CASE WHEN premium < 1000 THEN '<1000'\n            WHEN premium < 2500 THEN '1000-2499'\n            ELSE '2500+' END AS bucket,\n       COUNT(*) AS n\nFROM policies\nGROUP BY 1\nORDER BY 1;","explanation":"CASE evaluates top-down, so the second branch only sees premium >= 1000.","ordered":true,"similar":null,"columns":["bucket","n"],"expected":["1000-2499␟12.00","2500+␟4.00","<1000␟7.00"],"tables":["policies"]},{"id":"q12","tier":"easy","topic":"distinct","title":"Distinct buyers","prompt":"From orders, how many distinct users have at least one order with status 'complete'? Return one column buyers.","hint":"COUNT(DISTINCT ...).","solution":"SELECT COUNT(DISTINCT user_id) AS buyers\nFROM orders\nWHERE status = 'complete';","explanation":"COUNT(DISTINCT) vs COUNT(*) is a classic trap.","ordered":false,"similar":null,"columns":["buyers"],"expected":["11.00"],"tables":["orders"]},{"id":"q13","tier":"easy","topic":"self-join","title":"Employee and manager","prompt":"From employees (manager_id references emp_id), return name and manager (the manager's name, NULL for the top person). Order by emp_id.","hint":"LEFT JOIN employees to itself.","solution":"SELECT e.name, m.name AS manager\nFROM employees e\nLEFT JOIN employees m ON m.emp_id = e.manager_id\nORDER BY e.emp_id;","explanation":"LEFT JOIN keeps the person with no manager.","ordered":true,"similar":{"url":"https://leetcode.com/problems/employees-earning-more-than-their-managers/","title":"LeetCode: Employees Earning More Than Their Managers"},"columns":["name","manager"],"expected":["Mira␟NULL","Raj␟Mira","Sol␟Mira","Tess␟Raj","Uma␟Raj","Vic␟Tess","Wes␟Sol","Xia␟Sol","Yuri␟Wes","Zoe␟Tess","Ari␟Wes"],"tables":["employees"]},{"id":"q14","tier":"easy","topic":"aggregation","title":"Highest salary per department","prompt":"From employees, return dept and max_salary. Order by dept.","hint":"GROUP BY dept.","solution":"SELECT dept, MAX(salary) AS max_salary\nFROM employees\nGROUP BY dept\nORDER BY dept;","explanation":"To return the person, you need DISTINCT ON or a window (see medium).","ordered":true,"similar":{"url":"https://leetcode.com/problems/department-highest-salary/","title":"LeetCode: Department Highest Salary"},"columns":["dept","max_salary"],"expected":["Data␟190000.00","Eng␟200000.00","Exec␟250000.00"],"tables":["employees"]},{"id":"q15","tier":"easy","topic":"null","title":"Referral default","prompt":"From customers, return name and referrer (referred_by, or 0 when NULL). Order by customer_id.","hint":"COALESCE.","solution":"SELECT name, COALESCE(referred_by, 0) AS referrer\nFROM customers\nORDER BY customer_id;","explanation":"COALESCE returns the first non-NULL argument.","ordered":true,"similar":null,"columns":["name","referrer"],"expected":["Ava␟0.00","Ben␟0.00","Cara␟0.00","Dev␟0.00","Eli␟0.00","Fay␟3.00","Gus␟0.00","Hana␟0.00","Ivan␟3.00","Jo␟0.00","Kai␟0.00","Lena␟7.00"],"tables":["customers"]},{"id":"q16","tier":"easy","topic":"filtering","title":"Active policies in CA or TX","prompt":"From policies, return policy_id for ACTIVE policies in CA or TX. Order by policy_id.","hint":"IN ('CA','TX').","solution":"SELECT policy_id\nFROM policies\nWHERE status = 'ACTIVE' AND state IN ('CA', 'TX')\nORDER BY policy_id;","explanation":"Mixing AND with OR without parentheses is a common bug; IN avoids it.","ordered":true,"similar":null,"columns":["policy_id"],"expected":["109.00","114.00","115.00","119.00","121.00","122.00"],"tables":["policies"]},{"id":"q17","tier":"easy","topic":"aggregation","title":"Refund share","prompt":"From orders, return refund_pct = percent of all orders with status 'refunded', 1 decimal.","hint":"COUNT(*) FILTER (WHERE status = 'refunded').","solution":"SELECT ROUND(100.0 * COUNT(*) FILTER (WHERE status = 'refunded') / COUNT(*), 1) AS refund_pct\nFROM orders;","explanation":"Conditional aggregation with FILTER.","ordered":false,"similar":null,"columns":["refund_pct"],"expected":["20.00"],"tables":["orders"]},{"id":"q18","tier":"easy","topic":"union","title":"Earliest touchpoint dates","prompt":"Tables: quotes, policies. Return a single column d with the 5 earliest distinct dates on which a quote was created (quote_date) or a policy became effective (effective_date).","hint":"UNION removes duplicates; UNION ALL keeps them. Postgres requires an alias on a subquery in FROM (older versions).","solution":"SELECT d FROM (\n  SELECT quote_date AS d FROM quotes\n  UNION\n  SELECT effective_date FROM policies\n) t\nORDER BY d\nLIMIT 5;","explanation":"UNION dedupes (costly on big data); use UNION ALL when rows are known distinct.","ordered":true,"similar":null,"columns":["d"],"expected":["2024-01-24","2024-01-28","2024-02-07","2024-03-12","2024-03-13"],"tables":["policies","quotes"]},{"id":"q19","tier":"easy","topic":"aggregation","title":"Users by country and plan","prompt":"From users, return country, plan, n. Order by country, plan.","hint":"GROUP BY two columns.","solution":"SELECT country, plan, COUNT(*) AS n\nFROM users\nGROUP BY country, plan\nORDER BY country, plan;","explanation":"Multi-column grouping.","ordered":true,"similar":null,"columns":["country","plan","n"],"expected":["CA␟free␟1.00","CA␟team␟1.00","DE␟free␟1.00","DE␟pro␟1.00","UK␟free␟1.00","UK␟team␟1.00","US␟free␟2.00","US␟pro␟2.00","US␟team␟2.00"],"tables":["users"]},{"id":"q20","tier":"easy","topic":"subquery","title":"Above-average premium","prompt":"From policies, return policy_id and premium for policies whose premium is above the average premium of all policies. Order by policy_id.","hint":"Scalar subquery in WHERE.","solution":"SELECT policy_id, premium\nFROM policies\nWHERE premium > (SELECT AVG(premium) FROM policies)\nORDER BY policy_id;","explanation":"A scalar subquery is evaluated once.","ordered":true,"similar":null,"columns":["policy_id","premium"],"expected":["101.00␟3341.66","109.00␟4009.08","110.00␟2649.89","111.00␟2420.34","113.00␟1678.25","120.00␟2364.91","122.00␟3366.46"],"tables":["policies"]},{"id":"q21","tier":"medium","topic":"window","title":"Rank premium within state","prompt":"From policies, return state, policy_id, premium and rnk = dense rank of premium within the state (highest = 1). Order by state, rnk, policy_id.","hint":"DENSE_RANK() OVER (PARTITION BY state ORDER BY premium DESC).","solution":"SELECT state, policy_id, premium,\n  DENSE_RANK() OVER (PARTITION BY state ORDER BY premium DESC) AS rnk\nFROM policies\nORDER BY state, rnk, policy_id;","explanation":"ROW_NUMBER: unique; RANK: gaps after ties; DENSE_RANK: no gaps.","ordered":true,"similar":{"url":"https://leetcode.com/problems/rank-scores/","title":"LeetCode: Rank Scores"},"columns":["state","policy_id","premium","rnk"],"expected":["CA␟109.00␟4009.08␟1.00","CA␟122.00␟3366.46␟2.00","CA␟101.00␟3341.66␟3.00","CA␟120.00␟2364.91␟4.00","CA␟113.00␟1678.25␟5.00","CA␟115.00␟1418.39␟6.00","CA␟121.00␟1360.15␟7.00","CA␟108.00␟1117.10␟8.00","CA␟114.00␟748.34␟9.00","FL␟117.00␟1617.47␟1.00","FL␟107.00␟1274.65␟2.00","FL␟106.00␟1096.77␟3.00","FL␟116.00␟903.50␟4.00","FL␟105.00␟858.50␟5.00","NY␟111.00␟2420.34␟1.00","NY␟123.00␟1345.81␟2.00","NY␟112.00␟1109.47␟3.00","NY␟104.00␟947.39␟4.00","NY␟103.00␟852.25␟5.00","TX␟110.00␟2649.89␟1.00","TX␟102.00␟1093.50␟2.00","TX␟118.00␟946.72␟3.00","TX␟119.00␟734.56␟4.00"],"tables":["policies"]},{"id":"q22","tier":"medium","topic":"top-n","title":"Top 2 earners per department","prompt":"From employees, return name, dept, salary for the two highest-paid people in each department. Order by dept, salary desc.","hint":"ROW_NUMBER in a CTE, then filter rn <= 2.","solution":"WITH r AS (\n  SELECT name, dept, salary,\n    ROW_NUMBER() OVER (PARTITION BY dept ORDER BY salary DESC) AS rn\n  FROM employees)\nSELECT name, dept, salary FROM r\nWHERE rn <= 2\nORDER BY dept, salary DESC;","explanation":"Top-N per group = window rank + filter. You can't filter a window function in WHERE of the same SELECT (Databricks/Snowflake have QUALIFY; Postgres doesn't).","ordered":true,"similar":{"url":"https://leetcode.com/problems/department-top-three-salaries/","title":"LeetCode: Department Top Three Salaries"},"columns":["name","dept","salary"],"expected":["Raj␟Data␟190000.00","Zoe␟Data␟160000.00","Sol␟Eng␟200000.00","Ari␟Eng␟170000.00","Mira␟Exec␟250000.00"],"tables":["employees"]},{"id":"q23","tier":"medium","topic":"running","title":"Running written premium","prompt":"From policies, ordered by effective_date then policy_id, return policy_id, effective_date, premium and running = cumulative premium.","hint":"SUM() OVER (ORDER BY ... ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW).","solution":"SELECT policy_id, effective_date, premium,\n  SUM(premium) OVER (ORDER BY effective_date, policy_id\n    ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running\nFROM policies\nORDER BY effective_date, policy_id;","explanation":"An explicit ROWS frame avoids RANGE's tie behavior.","ordered":true,"similar":{"url":"https://leetcode.com/problems/last-person-to-fit-in-the-bus/","title":"LeetCode: Last Person to Fit in the Bus"},"columns":["policy_id","effective_date","premium","running"],"expected":["101.00␟2024-03-29␟3341.66␟3341.66","102.00␟2024-05-03␟1093.50␟4435.16","103.00␟2024-06-04␟852.25␟5287.41","105.00␟2024-07-18␟858.50␟6145.91","108.00␟2024-08-22␟1117.10␟7263.01","110.00␟2024-09-28␟2649.89␟9912.90","111.00␟2024-10-30␟2420.34␟12333.24","113.00␟2024-12-02␟1678.25␟14011.49","116.00␟2025-01-14␟903.50␟14914.99","118.00␟2025-02-23␟946.72␟15861.71","120.00␟2025-03-23␟2364.91␟18226.62","123.00␟2025-04-21␟1345.81␟19572.43","104.00␟2025-06-04␟947.39␟20519.82","109.00␟2025-08-22␟4009.08␟24528.90","106.00␟2025-09-01␟1096.77␟25625.67","112.00␟2025-10-30␟1109.47␟26735.14","114.00␟2025-12-02␟748.34␟27483.48","117.00␟2026-01-14␟1617.47␟29100.95","119.00␟2026-04-09␟734.56␟29835.51","121.00␟2026-05-07␟1360.15␟31195.66","107.00␟2026-07-18␟1274.65␟32470.31","115.00␟2027-01-16␟1418.39␟33888.70","122.00␟2027-05-07␟3366.46␟37255.16"],"tables":["policies"]},{"id":"q24","tier":"medium","topic":"lag","title":"Renewal rate change","prompt":"From policies, a renewal is a customer's next policy of the same product. For each renewal return customer_id, policy_id, prev (prior term's premium) and pct_change (1 decimal). Order by customer_id, policy_id.","hint":"LAG(premium) OVER (PARTITION BY customer_id, product ORDER BY effective_date).","solution":"WITH x AS (\n  SELECT customer_id, policy_id, premium,\n    LAG(premium) OVER (PARTITION BY customer_id, product ORDER BY effective_date) AS prev\n  FROM policies)\nSELECT customer_id, policy_id, prev,\n  ROUND(100.0 * (premium - prev) / prev, 1) AS pct_change\nFROM x\nWHERE prev IS NOT NULL\nORDER BY customer_id, policy_id;","explanation":"Renewal rate change is a core pricing metric.","ordered":true,"similar":null,"columns":["customer_id","policy_id","prev","pct_change"],"expected":["3.00␟104.00␟852.25␟11.20","4.00␟106.00␟858.50␟27.80","4.00␟107.00␟1096.77␟16.20","5.00␟109.00␟1117.10␟258.90","7.00␟112.00␟2420.34␟-54.20","8.00␟114.00␟1678.25␟-55.40","8.00␟115.00␟748.34␟89.50","9.00␟117.00␟903.50␟79.00","10.00␟119.00␟946.72␟-22.40","11.00␟121.00␟2364.91␟-42.50","11.00␟122.00␟1360.15␟147.50"],"tables":["policies"]},{"id":"q25","tier":"medium","topic":"dedup","title":"Detect duplicate logins","prompt":"From logins, return user_id, raw_rows and distinct_days per user. Order by user_id.","hint":"COUNT(*) vs COUNT(DISTINCT login_date).","solution":"SELECT user_id, COUNT(*) AS raw_rows, COUNT(DISTINCT login_date) AS distinct_days\nFROM logins\nGROUP BY user_id\nORDER BY user_id;","explanation":"Measure duplication before fixing it.","ordered":true,"similar":null,"columns":["user_id","raw_rows","distinct_days"],"expected":["1.00␟5.00␟4.00","2.00␟10.00␟9.00","3.00␟7.00␟6.00","4.00␟5.00␟5.00","5.00␟6.00␟5.00","6.00␟8.00␟7.00","7.00␟4.00␟4.00","8.00␟9.00␟8.00"],"tables":["logins"]},{"id":"q26","tier":"medium","topic":"dedup","title":"Latest claim per policy","prompt":"From claims, for each policy_id keep only the most recently reported claim (ties: higher claim_id). Return policy_id, claim_id, report_date ordered by policy_id.","hint":"DISTINCT ON (policy_id) with ORDER BY policy_id, report_date DESC, claim_id DESC.","solution":"SELECT DISTINCT ON (policy_id) policy_id, claim_id, report_date\nFROM claims\nORDER BY policy_id, report_date DESC, claim_id DESC;","explanation":"DISTINCT ON is Postgres's shortcut for 'first row per group'. Portable version: ROW_NUMBER() ... WHERE rn = 1.","ordered":true,"similar":null,"columns":["policy_id","claim_id","report_date"],"expected":["101.00␟24.00␟2024-05-03","105.00␟16.00␟2025-04-25","106.00␟10.00␟2025-11-01","107.00␟12.00␟2027-06-05","108.00␟18.00␟2025-06-02","109.00␟21.00␟2026-04-25","112.00␟13.00␟2026-07-02","113.00␟2.00␟2025-09-14","115.00␟8.00␟2027-11-06","116.00␟9.00␟2025-12-12","118.00␟6.00␟2025-09-12","119.00␟5.00␟2026-07-16","120.00␟19.00␟2025-09-01","123.00␟7.00␟2026-01-21"],"tables":["claims"]},{"id":"q27","tier":"medium","topic":"joins","title":"Loss ratio by product","prompt":"Tables: policies, claims. Loss ratio = SUM(paid_amount + reserve_amount) / SUM(premium) per product, 3 decimals; products with no claims show 0. Return product, loss_ratio ordered by product.","hint":"Fan-out trap: joining policies to claims first duplicates premium. Aggregate each side separately.","solution":"WITH prem AS (\n  SELECT product, SUM(premium) AS p FROM policies GROUP BY product),\nloss AS (\n  SELECT p.product, SUM(c.paid_amount + c.reserve_amount) AS l\n  FROM claims c JOIN policies p ON p.policy_id = c.policy_id\n  GROUP BY p.product)\nSELECT prem.product, ROUND(COALESCE(l, 0) / p, 3) AS loss_ratio\nFROM prem LEFT JOIN loss USING (product)\nORDER BY prem.product;","explanation":"Aggregate each fact to the shared grain before joining. Note this is written premium, not earned.","ordered":true,"similar":null,"columns":["product","loss_ratio"],"expected":["Auto␟2.40","BOP␟2.89","GL␟7.75","WC␟3.62"],"tables":["claims","policies"]},{"id":"q28","tier":"medium","topic":"pivot","title":"Claims by cause pivot","prompt":"Tables: claims, policies. One row per product with columns water, fire, theft, injury, collision = number of claims of that cause. Order by product.","hint":"COUNT(*) FILTER (WHERE cause = 'Water') AS water, ...","solution":"SELECT p.product,\n  COUNT(*) FILTER (WHERE cause = 'Water') AS water,\n  COUNT(*) FILTER (WHERE cause = 'Fire') AS fire,\n  COUNT(*) FILTER (WHERE cause = 'Theft') AS theft,\n  COUNT(*) FILTER (WHERE cause = 'Injury') AS injury,\n  COUNT(*) FILTER (WHERE cause = 'Collision') AS collision\nFROM claims c\nJOIN policies p ON p.policy_id = c.policy_id\nGROUP BY p.product\nORDER BY p.product;","explanation":"FILTER pivots are clean in Postgres; SUM(CASE ...) is the portable form.","ordered":true,"similar":{"url":"https://leetcode.com/problems/reformat-department-table/","title":"LeetCode: Reformat Department Table"},"columns":["product","water","fire","theft","injury","collision"],"expected":["Auto␟0.00␟1.00␟1.00␟1.00␟0.00","BOP␟1.00␟1.00␟0.00␟1.00␟0.00","GL␟5.00␟1.00␟2.00␟2.00␟1.00","WC␟2.00␟1.00␟2.00␟2.00␟0.00"],"tables":["claims","policies"]},{"id":"q29","tier":"medium","topic":"window","title":"Share of state premium","prompt":"From policies, return policy_id, state and pct_of_state = premium as % of its state's total premium (1 decimal). Order by state, policy_id.","hint":"SUM(premium) OVER (PARTITION BY state).","solution":"SELECT policy_id, state,\n  ROUND(100.0 * premium / SUM(premium) OVER (PARTITION BY state), 1) AS pct_of_state\nFROM policies\nORDER BY state, policy_id;","explanation":"Window aggregates keep row detail without a self-join.","ordered":true,"similar":null,"columns":["policy_id","state","pct_of_state"],"expected":["101.00␟CA␟17.20","108.00␟CA␟5.80","109.00␟CA␟20.70","113.00␟CA␟8.60","114.00␟CA␟3.90","115.00␟CA␟7.30","120.00␟CA␟12.20","121.00␟CA␟7.00","122.00␟CA␟17.30","105.00␟FL␟14.90","106.00␟FL␟19.10","107.00␟FL␟22.20","116.00␟FL␟15.70","117.00␟FL␟28.10","103.00␟NY␟12.80","104.00␟NY␟14.20","111.00␟NY␟36.30","112.00␟NY␟16.60","123.00␟NY␟20.20","102.00␟TX␟20.20","110.00␟TX␟48.80","118.00␟TX␟17.50","119.00␟TX␟13.50"],"tables":["policies"]},{"id":"q30","tier":"medium","topic":"dates","title":"Monthly revenue with MoM growth","prompt":"From orders (status 'complete' only), return mon (month start date), rev (2 decimals) and mom_pct (% change vs previous month, 1 decimal). Order by mon.","hint":"Aggregate by DATE_TRUNC in a CTE, then LAG.","solution":"WITH m AS (\n  SELECT DATE_TRUNC('month', order_date)::date AS mon, SUM(amount) AS rev\n  FROM orders WHERE status = 'complete'\n  GROUP BY 1)\nSELECT mon, ROUND(rev, 2) AS rev,\n  ROUND(100.0 * (rev - LAG(rev) OVER (ORDER BY mon)) / LAG(rev) OVER (ORDER BY mon), 1) AS mom_pct\nFROM m\nORDER BY mon;","explanation":"Aggregate first, window second.","ordered":true,"similar":null,"columns":["mon","rev","mom_pct"],"expected":["2025-01-01␟662.21␟NULL","2025-02-01␟1372.16␟107.20","2025-03-01␟169.50␟-87.60","2025-04-01␟417.82␟146.50","2025-05-01␟1149.65␟175.20","2025-06-01␟794.82␟-30.90","2025-07-01␟1414.12␟77.90","2025-08-01␟355.86␟-74.80","2025-09-01␟1446.25␟306.40","2025-10-01␟880.24␟-39.10"],"tables":["orders"]},{"id":"q31","tier":"medium","topic":"self-join","title":"Cross-state referrals","prompt":"From customers (referred_by references customer_id), return referrer and referee names where the two live in different states. Order by referrer, referee.","hint":"Join customers to itself on c.referred_by = r.customer_id.","solution":"SELECT r.name AS referrer, c.name AS referee\nFROM customers c\nJOIN customers r ON r.customer_id = c.referred_by\nWHERE r.state <> c.state\nORDER BY referrer, referee;","explanation":"Self joins model relationships within one entity.","ordered":true,"similar":null,"columns":["referrer","referee"],"expected":["Cara␟Fay","Cara␟Ivan"],"tables":["customers"]},{"id":"q32","tier":"medium","topic":"funnel","title":"Event funnel","prompt":"From events, return one row with columns visit, signup, add_to_cart, purchase = distinct users who did each event_type.","hint":"COUNT(DISTINCT user_id) FILTER (WHERE event_type = ...).","solution":"SELECT\n  COUNT(DISTINCT user_id) FILTER (WHERE event_type = 'visit') AS visit,\n  COUNT(DISTINCT user_id) FILTER (WHERE event_type = 'signup') AS signup,\n  COUNT(DISTINCT user_id) FILTER (WHERE event_type = 'add_to_cart') AS add_to_cart,\n  COUNT(DISTINCT user_id) FILTER (WHERE event_type = 'purchase') AS purchase\nFROM events;","explanation":"A loose funnel. A strict funnel requires steps in order (see hard).","ordered":false,"similar":null,"columns":["visit","signup","add_to_cart","purchase"],"expected":["12.00␟10.00␟6.00␟1.00"],"tables":["events"]},{"id":"q33","tier":"medium","topic":"funnel","title":"Quote funnel by month","prompt":"From quotes, return mon (month start), quotes, binds and bind_pct (1 decimal). Order by mon.","hint":"COUNT(*) FILTER (WHERE bound).","solution":"SELECT DATE_TRUNC('month', quote_date)::date AS mon,\n  COUNT(*) AS quotes,\n  COUNT(*) FILTER (WHERE bound) AS binds,\n  ROUND(100.0 * COUNT(*) FILTER (WHERE bound) / COUNT(*), 1) AS bind_pct\nFROM quotes\nGROUP BY 1\nORDER BY 1;","explanation":"Quote metrics are daily work at an insurtech.","ordered":true,"similar":{"url":"https://leetcode.com/problems/monthly-transactions-i/","title":"LeetCode: Monthly Transactions I"},"columns":["mon","quotes","binds","bind_pct"],"expected":["2024-01-01␟2.00␟0.00␟0.00","2024-02-01␟1.00␟0.00␟0.00","2024-03-01␟4.00␟0.00␟0.00","2024-04-01␟1.00␟0.00␟0.00","2024-07-01␟2.00␟1.00␟50.00","2024-08-01␟2.00␟0.00␟0.00","2024-09-01␟1.00␟0.00␟0.00","2024-10-01␟1.00␟0.00␟0.00","2024-12-01␟1.00␟1.00␟100.00","2025-01-01␟1.00␟0.00␟0.00","2025-02-01␟1.00␟0.00␟0.00","2025-03-01␟1.00␟0.00␟0.00","2025-04-01␟1.00␟0.00␟0.00","2025-05-01␟4.00␟0.00␟0.00","2025-08-01␟1.00␟1.00␟100.00","2025-09-01␟2.00␟1.00␟50.00","2026-01-01␟3.00␟1.00␟33.30","2026-03-01␟1.00␟1.00␟100.00"],"tables":["quotes"]},{"id":"q34","tier":"medium","topic":"subquery","title":"Above their state's average","prompt":"Tables: customers, policies. Return name, state and tot (total premium across the customer's policies, 2 decimals) for customers whose total exceeds the average customer total in their state. Order by state, name.","hint":"CTE of customer totals, then AVG(tot) OVER (PARTITION BY state).","solution":"WITH t AS (\n  SELECT c.customer_id, c.name, c.state, SUM(p.premium) AS tot\n  FROM customers c JOIN policies p ON p.customer_id = c.customer_id\n  GROUP BY c.customer_id, c.name, c.state),\ns AS (SELECT *, AVG(tot) OVER (PARTITION BY state) AS st_avg FROM t)\nSELECT name, state, ROUND(tot, 2) AS tot\nFROM s WHERE tot > st_avg\nORDER BY state, name;","explanation":"Correlated-subquery problems are often cleaner as window aggregates.","ordered":true,"similar":null,"columns":["name","state","tot"],"expected":["Eli␟CA␟5126.18","Kai␟CA␟7091.52","Dev␟FL␟3229.92","Gus␟NY␟3529.81","Fay␟TX␟2649.89"],"tables":["customers","policies"]},{"id":"q35","tier":"medium","topic":"window","title":"Second highest salary","prompt":"From employees, return second_highest = the second highest distinct salary (NULL if it doesn't exist).","hint":"DENSE_RANK = 2, or MAX(salary) WHERE salary < MAX.","solution":"SELECT MAX(salary) AS second_highest\nFROM employees\nWHERE salary < (SELECT MAX(salary) FROM employees);","explanation":"The DENSE_RANK version generalizes to Nth highest.","ordered":false,"similar":{"url":"https://leetcode.com/problems/second-highest-salary/","title":"LeetCode: Second Highest Salary"},"columns":["second_highest"],"expected":["200000.00"],"tables":["employees"]},{"id":"q36","tier":"medium","topic":"dates","title":"Days since last loss","prompt":"Tables: claims, policies. For each customer with at least one claim, return customer_id, last_loss (latest loss_date) and days_since = days from last_loss to DATE '2026-06-30'. Order by customer_id.","hint":"DATE '2026-06-30' - MAX(loss_date).","solution":"SELECT p.customer_id, MAX(c.loss_date) AS last_loss,\n  DATE '2026-06-30' - MAX(c.loss_date) AS days_since\nFROM claims c\nJOIN policies p ON p.policy_id = c.policy_id\nGROUP BY p.customer_id\nORDER BY p.customer_id;","explanation":"Typed literals (DATE '...') or '...'::date avoid implicit text comparisons.","ordered":true,"similar":null,"columns":["customer_id","last_loss","days_since"],"expected":["1.00␟2024-05-03␟788.00","4.00␟2027-05-31␟-335.00","5.00␟2026-04-23␟68.00","7.00␟2026-07-02␟-2.00","8.00␟2027-11-01␟-489.00","9.00␟2025-12-07␟205.00","10.00␟2026-07-14␟-14.00","11.00␟2025-07-03␟362.00","12.00␟2026-01-12␟169.00"],"tables":["claims","policies"]},{"id":"q37","tier":"medium","topic":"window","title":"3-order moving average","prompt":"From orders, per user return user_id, order_id, order_date and ma3 = average amount of the current and 2 previous orders (by order_date, order_id), 2 decimals. Order by user_id, order_date, order_id.","hint":"AVG() OVER (PARTITION BY user_id ORDER BY ... ROWS BETWEEN 2 PRECEDING AND CURRENT ROW).","solution":"SELECT user_id, order_id, order_date,\n  ROUND(AVG(amount) OVER (PARTITION BY user_id ORDER BY order_date, order_id\n    ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), 2) AS ma3\nFROM orders\nORDER BY user_id, order_date, order_id;","explanation":"ROWS counts rows; RANGE uses value distance (in Postgres RANGE can take an INTERVAL offset on dates).","ordered":true,"similar":{"url":"https://leetcode.com/problems/restaurant-growth/","title":"LeetCode: Restaurant Growth"},"columns":["user_id","order_id","order_date","ma3"],"expected":["1.00␟10.00␟2025-01-12␟19.03","1.00␟16.00␟2025-02-10␟167.75","1.00␟4.00␟2025-06-27␟277.57","1.00␟19.00␟2025-08-28␟304.83","1.00␟30.00␟2025-09-24␟305.14","2.00␟33.00␟2025-01-20␟30.51","2.00␟6.00␟2025-03-28␟84.42","2.00␟3.00␟2025-05-20␟200.53","2.00␟1.00␟2025-05-22␟346.96","2.00␟34.00␟2025-07-16␟440.70","2.00␟12.00␟2025-08-14␟407.01","2.00␟27.00␟2025-10-31␟410.16","3.00␟29.00␟2025-05-30␟364.84","4.00␟7.00␟2025-06-13␟318.05","4.00␟22.00␟2025-07-06␟208.85","4.00␟24.00␟2025-09-20␟269.35","5.00␟39.00␟2025-02-12␟424.61","5.00␟2.00␟2025-02-16␟366.31","5.00␟25.00␟2025-02-19␟271.04","5.00␟5.00␟2025-03-12␟139.89","5.00␟9.00␟2025-07-01␟171.82","5.00␟8.00␟2025-08-21␟230.00","6.00␟14.00␟2025-04-16␟417.82","7.00␟26.00␟2025-01-16␟156.83","7.00␟23.00␟2025-02-16␟199.71","7.00␟17.00␟2025-03-29␟145.52","7.00␟15.00␟2025-07-01␟256.95","8.00␟20.00␟2025-01-06␟138.99","8.00␟36.00␟2025-05-20␟75.31","9.00␟18.00␟2025-05-29␟303.40","9.00␟13.00␟2025-06-11␟325.20","9.00␟21.00␟2025-06-19␟260.06","9.00␟11.00␟2025-09-05␟202.38","9.00␟31.00␟2025-09-20␟182.90","11.00␟35.00␟2025-01-14␟316.85","11.00␟28.00␟2025-07-23␟350.68","11.00␟38.00␟2025-10-01␟247.91","11.00␟32.00␟2025-10-31␟275.96","12.00␟40.00␟2025-04-20␟123.06","12.00␟37.00␟2025-09-19␟286.51"],"tables":["orders"]},{"id":"q38","tier":"medium","topic":"joins","title":"Cross-sell gaps","prompt":"Tables: customers, policies. Count every (customer, product) combination where the customer has never held a policy of that product (products = distinct products in policies). Return one column gaps.","hint":"CROSS JOIN customers with distinct products, then NOT EXISTS.","solution":"SELECT COUNT(*) AS gaps\nFROM customers c\nCROSS JOIN (SELECT DISTINCT product FROM policies) pr\nWHERE NOT EXISTS (\n  SELECT 1 FROM policies p\n  WHERE p.customer_id = c.customer_id AND p.product = pr.product);","explanation":"A densification pattern: build all combinations, then subtract what exists.","ordered":false,"similar":null,"columns":["gaps"],"expected":["36.00"],"tables":["customers","policies"]},{"id":"q39","tier":"medium","topic":"case","title":"Tenure segment","prompt":"From policies, return customer_id, terms (number of policies) and seg: 'new' (1), 'renewing' (2), 'loyal' (3+). Order by customer_id.","hint":"COUNT(*) then CASE on it.","solution":"SELECT customer_id, COUNT(*) AS terms,\n  CASE WHEN COUNT(*) = 1 THEN 'new'\n       WHEN COUNT(*) = 2 THEN 'renewing'\n       ELSE 'loyal' END AS seg\nFROM policies\nGROUP BY customer_id\nORDER BY customer_id;","explanation":"CASE over aggregates is allowed in SELECT.","ordered":true,"similar":null,"columns":["customer_id","terms","seg"],"expected":["1.00␟1.00␟new","2.00␟1.00␟new","3.00␟2.00␟renewing","4.00␟3.00␟loyal","5.00␟2.00␟renewing","6.00␟1.00␟new","7.00␟2.00␟renewing","8.00␟3.00␟loyal","9.00␟2.00␟renewing","10.00␟2.00␟renewing","11.00␟3.00␟loyal","12.00␟1.00␟new"],"tables":["policies"]},{"id":"q40","tier":"medium","topic":"ranking","title":"Severity percentile","prompt":"From claims, return claim_id, cause, incurred (paid + reserve) and pr = PERCENT_RANK of incurred within the cause (2 decimals). Order by cause, pr, claim_id.","hint":"PERCENT_RANK() returns double precision, so cast to numeric before ROUND.","solution":"SELECT claim_id, cause, paid_amount + reserve_amount AS incurred,\n  ROUND((PERCENT_RANK() OVER (PARTITION BY cause ORDER BY paid_amount + reserve_amount))::numeric, 2) AS pr\nFROM claims\nORDER BY cause, pr, claim_id;","explanation":"Postgres gotcha: ROUND(double precision, int) doesn't exist; cast with ::numeric.","ordered":true,"similar":null,"columns":["claim_id","cause","incurred","pr"],"expected":["12.00␟Collision␟11537.87␟0.00","6.00␟Fire␟3003.78␟0.00","18.00␟Fire␟3101.05␟0.33","3.00␟Fire␟7980.90␟0.67","19.00␟Fire␟11970.63␟1.00","5.00␟Injury␟236.02␟0.00","1.00␟Injury␟909.12␟0.20","4.00␟Injury␟4024.57␟0.40","9.00␟Injury␟7793.03␟0.60","21.00␟Injury␟12055.02␟0.80","13.00␟Injury␟13632.70␟1.00","22.00␟Theft␟4184.42␟0.00","14.00␟Theft␟6091.44␟0.25","15.00␟Theft␟7742.01␟0.50","17.00␟Theft␟8192.68␟0.75","2.00␟Theft␟12661.57␟1.00","10.00␟Water␟662.67␟0.00","23.00␟Water␟1500.00␟0.14","24.00␟Water␟1500.00␟0.14","16.00␟Water␟2823.19␟0.43","8.00␟Water␟3711.01␟0.57","7.00␟Water␟6150.56␟0.71","20.00␟Water␟6632.84␟0.86","11.00␟Water␟12426.30␟1.00"],"tables":["claims"]},{"id":"q41","tier":"medium","topic":"dates","title":"Policies in force on a date","prompt":"From policies, how many non-cancelled policies were in force on 2025-06-30 (effective_date <= date < expiration_date)? Return in_force.","hint":"Half-open interval; compare to DATE '2025-06-30'.","solution":"SELECT COUNT(*) AS in_force\nFROM policies\nWHERE effective_date <= DATE '2025-06-30'\n  AND expiration_date > DATE '2025-06-30'\n  AND status <> 'CANCELLED';","explanation":"Half-open [start, end) avoids double counting renewal days. Postgres also has daterange(effective_date, expiration_date) @> date.","ordered":false,"similar":null,"columns":["in_force"],"expected":["8.00"],"tables":["policies"]},{"id":"q42","tier":"medium","topic":"cte","title":"First quote bound","prompt":"From quotes, return customer_id of customers whose earliest quote (by quote_date, then quote_id) was bound. Order by customer_id.","hint":"DISTINCT ON (customer_id) ... ORDER BY customer_id, quote_date, quote_id.","solution":"SELECT customer_id FROM (\n  SELECT DISTINCT ON (customer_id) customer_id, bound\n  FROM quotes\n  ORDER BY customer_id, quote_date, quote_id) f\nWHERE bound\nORDER BY customer_id;","explanation":"First-touch analysis with DISTINCT ON.","ordered":true,"similar":{"url":"https://leetcode.com/problems/immediate-food-delivery-ii/","title":"LeetCode: Immediate Food Delivery II"},"columns":["customer_id"],"expected":["5.00"],"tables":["quotes"]},{"id":"q43","tier":"medium","topic":"aggregation","title":"Orders-per-user distribution","prompt":"Tables: users, orders. How many users placed 0, 1, 2, ... complete orders? Include users with zero. Return orders, users ordered by orders.","hint":"LEFT JOIN with the status filter in the ON clause.","solution":"WITH c AS (\n  SELECT u.user_id, COUNT(o.order_id) AS n\n  FROM users u\n  LEFT JOIN orders o ON o.user_id = u.user_id AND o.status = 'complete'\n  GROUP BY u.user_id)\nSELECT n AS orders, COUNT(*) AS users\nFROM c GROUP BY n ORDER BY n;","explanation":"A filter on the right table in WHERE turns a LEFT JOIN into an INNER JOIN.","ordered":true,"similar":null,"columns":["orders","users"],"expected":["0.00␟1.00","1.00␟3.00","2.00␟2.00","3.00␟2.00","4.00␟2.00","5.00␟1.00","6.00␟1.00"],"tables":["orders","users"]},{"id":"q44","tier":"hard","topic":"gaps-islands","title":"Longest login streak","prompt":"From logins (may contain duplicate rows per day), return user_id and longest_streak = longest run of consecutive login days. Order by user_id.","hint":"Dedupe, then login_date - ROW_NUMBER()::int is constant within a streak.","solution":"WITH d AS (SELECT DISTINCT user_id, login_date FROM logins),\ng AS (\n  SELECT user_id, login_date,\n    login_date - (ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY login_date))::int AS grp\n  FROM d)\nSELECT user_id, MAX(len) AS longest_streak FROM (\n  SELECT user_id, grp, COUNT(*) AS len FROM g GROUP BY user_id, grp) s\nGROUP BY user_id\nORDER BY user_id;","explanation":"The canonical gaps-and-islands trick. date - integer = date in Postgres. Dedupe first or duplicates break it.","ordered":true,"similar":{"url":"https://leetcode.com/problems/consecutive-numbers/","title":"LeetCode: Consecutive Numbers"},"columns":["user_id","longest_streak"],"expected":["1.00␟4.00","2.00␟6.00","3.00␟2.00","4.00␟3.00","5.00␟2.00","6.00␟2.00","7.00␟3.00","8.00␟3.00"],"tables":["logins"]},{"id":"q45","tier":"hard","topic":"gaps-islands","title":"Continuous coverage periods","prompt":"From policies, merge each customer's overlapping or touching policy terms into continuous coverage periods. Return customer_id, cover_start, cover_end ordered by customer_id, cover_start.","hint":"New island when effective_date > running MAX(expiration_date) of earlier rows.","solution":"WITH t AS (\n  SELECT customer_id, policy_id, effective_date AS s, expiration_date AS e,\n    MAX(expiration_date) OVER (PARTITION BY customer_id ORDER BY effective_date, policy_id\n      ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) AS prev_end\n  FROM policies),\ng AS (\n  SELECT *, SUM(CASE WHEN prev_end IS NULL OR s > prev_end THEN 1 ELSE 0 END)\n    OVER (PARTITION BY customer_id ORDER BY s, policy_id ROWS UNBOUNDED PRECEDING) AS isl\n  FROM t)\nSELECT customer_id, MIN(s) AS cover_start, MAX(e) AS cover_end\nFROM g GROUP BY customer_id, isl\nORDER BY customer_id, cover_start;","explanation":"Interval merging: the insurance flavor of gaps-and-islands (lapse detection).","ordered":true,"similar":null,"columns":["customer_id","cover_start","cover_end"],"expected":["1.00␟2024-03-29␟2025-03-29","2.00␟2024-05-03␟2025-05-03","3.00␟2024-06-04␟2026-06-04","4.00␟2024-07-18␟2025-07-18","4.00␟2025-09-01␟2027-07-18","5.00␟2024-08-22␟2026-08-22","6.00␟2024-09-28␟2025-09-28","7.00␟2024-10-30␟2026-10-30","8.00␟2024-12-02␟2026-12-02","8.00␟2027-01-16␟2028-01-16","9.00␟2025-01-14␟2027-01-14","10.00␟2025-02-23␟2026-02-23","10.00␟2026-04-09␟2027-04-09","11.00␟2025-03-23␟2026-03-23","11.00␟2026-05-07␟2028-05-06","12.00␟2025-04-21␟2026-04-21"],"tables":["policies"]},{"id":"q46","tier":"hard","topic":"cohort","title":"Monthly retention cohorts","prompt":"Tables: users, orders. For users grouped by signup month (cohort, month start date), count distinct users with a complete order in month offset 0, 1 and 2 after signup (m0, m1, m2). Order by cohort.","hint":"Offset = months between DATE_TRUNC('month', order_date) and DATE_TRUNC('month', signup_date); use EXTRACT on AGE() or year*12+month.","solution":"WITH o AS (\n  SELECT u.user_id, DATE_TRUNC('month', u.signup_date)::date AS cohort,\n    (EXTRACT(YEAR FROM o.order_date) * 12 + EXTRACT(MONTH FROM o.order_date))\n    - (EXTRACT(YEAR FROM u.signup_date) * 12 + EXTRACT(MONTH FROM u.signup_date)) AS k\n  FROM users u\n  JOIN orders o ON o.user_id = u.user_id AND o.status = 'complete')\nSELECT cohort,\n  COUNT(DISTINCT user_id) FILTER (WHERE k = 0) AS m0,\n  COUNT(DISTINCT user_id) FILTER (WHERE k = 1) AS m1,\n  COUNT(DISTINCT user_id) FILTER (WHERE k = 2) AS m2\nFROM o GROUP BY cohort ORDER BY cohort;","explanation":"Month index = year*12 + month is robust; AGE() gives months only within the year part.","ordered":true,"similar":null,"columns":["cohort","m0","m1","m2"],"expected":["2025-01-01␟1.00␟1.00␟0.00","2025-02-01␟1.00␟0.00␟0.00","2025-03-01␟1.00␟1.00␟1.00","2025-04-01␟0.00␟0.00␟0.00","2025-05-01␟2.00␟1.00␟0.00"],"tables":["orders","users"]},{"id":"q47","tier":"hard","topic":"recursive","title":"Org chart depth","prompt":"From employees, return emp_id, name, lvl (top = 1) and path of names from the top joined with ' > '. Order by emp_id.","hint":"WITH RECURSIVE; anchor is manager_id IS NULL. Cast the path to text in the anchor.","solution":"WITH RECURSIVE t AS (\n  SELECT emp_id, name, 1 AS lvl, name::text AS path\n  FROM employees WHERE manager_id IS NULL\n  UNION ALL\n  SELECT e.emp_id, e.name, t.lvl + 1, t.path || ' > ' || e.name\n  FROM employees e JOIN t ON e.manager_id = t.emp_id)\nSELECT emp_id, name, lvl, path FROM t ORDER BY emp_id;","explanation":"Recursive CTE = anchor + recursive member. Postgres requires matching column types between them.","ordered":true,"similar":null,"columns":["emp_id","name","lvl","path"],"expected":["1.00␟Mira␟1.00␟Mira","2.00␟Raj␟2.00␟Mira > Raj","3.00␟Sol␟2.00␟Mira > Sol","4.00␟Tess␟3.00␟Mira > Raj > Tess","5.00␟Uma␟3.00␟Mira > Raj > Uma","6.00␟Vic␟4.00␟Mira > Raj > Tess > Vic","7.00␟Wes␟3.00␟Mira > Sol > Wes","8.00␟Xia␟3.00␟Mira > Sol > Xia","9.00␟Yuri␟4.00␟Mira > Sol > Wes > Yuri","10.00␟Zoe␟4.00␟Mira > Raj > Tess > Zoe","11.00␟Ari␟4.00␟Mira > Sol > Wes > Ari"],"tables":["employees"]},{"id":"q48","tier":"hard","topic":"spine","title":"Month spine with zero months","prompt":"Tables: orders. For every month start from 2025-01-01 through 2025-12-01, count complete orders (months with none show 0). Return month_start, orders.","hint":"generate_series(start, end, INTERVAL '1 month'), then LEFT JOIN.","solution":"SELECT m::date AS month_start, COUNT(o.order_id) AS orders\nFROM generate_series(DATE '2025-01-01', DATE '2025-12-01', INTERVAL '1 month') m\nLEFT JOIN orders o\n  ON DATE_TRUNC('month', o.order_date) = m AND o.status = 'complete'\nGROUP BY m\nORDER BY m;","explanation":"Date spines prevent missing periods (dbt_utils.date_spine; sequence()/explode in Databricks).","ordered":true,"similar":null,"columns":["month_start","orders"],"expected":["2025-01-01␟5.00","2025-02-01␟5.00","2025-03-01␟2.00","2025-04-01␟1.00","2025-05-01␟4.00","2025-06-01␟3.00","2025-07-01␟4.00","2025-08-01␟2.00","2025-09-01␟4.00","2025-10-01␟2.00","2025-11-01␟0.00","2025-12-01␟0.00"],"tables":["orders"]},{"id":"q49","tier":"hard","topic":"funnel","title":"Strict ordered funnel","prompt":"From events, return user_id of users who did visit, signup, add_to_cart and purchase with each step's first date on or after the previous step's first date. Order by user_id.","hint":"MIN(event_date) FILTER (WHERE event_type = ...) per user, then compare.","solution":"WITH s AS (\n  SELECT user_id,\n    MIN(event_date) FILTER (WHERE event_type = 'visit') AS v,\n    MIN(event_date) FILTER (WHERE event_type = 'signup') AS su,\n    MIN(event_date) FILTER (WHERE event_type = 'add_to_cart') AS a,\n    MIN(event_date) FILTER (WHERE event_type = 'purchase') AS p\n  FROM events GROUP BY user_id)\nSELECT user_id FROM s\nWHERE v <= su AND su <= a AND a <= p\nORDER BY user_id;","explanation":"Comparisons with NULL are unknown and get filtered out, which is what we want.","ordered":true,"similar":null,"columns":["user_id"],"expected":["1.00"],"tables":["events"]},{"id":"q50","tier":"hard","topic":"earned","title":"Earned premium in 2025","prompt":"From policies (excluding CANCELLED), compute earned_2025 = pro-rata premium earned during calendar 2025, 2 decimals. Earned = premium * overlap_days / term_days.","hint":"overlap = GREATEST(0, LEAST(expiration_date, DATE '2026-01-01') - GREATEST(effective_date, DATE '2025-01-01')).","solution":"SELECT ROUND(SUM(premium * GREATEST(0,\n    LEAST(expiration_date, DATE '2026-01-01') - GREATEST(effective_date, DATE '2025-01-01'))\n  / (expiration_date - effective_date)::numeric), 2) AS earned_2025\nFROM policies\nWHERE status <> 'CANCELLED';","explanation":"Interval overlap formula. LEAST/GREATEST are scalar; date - date is integer, so cast the denominator to numeric.","ordered":false,"similar":null,"columns":["earned_2025"],"expected":["12078.25"],"tables":["policies"]},{"id":"q51","tier":"hard","topic":"window","title":"Cumulative reported claims","prompt":"From claims, for each report_date return cum_claims (claims reported up to and including that date) and cum_incurred (2 decimals). Order by report_date.","hint":"Aggregate per date first, then running SUM.","solution":"WITH d AS (\n  SELECT report_date, COUNT(*) AS n, SUM(paid_amount + reserve_amount) AS inc\n  FROM claims GROUP BY report_date)\nSELECT report_date,\n  SUM(n) OVER (ORDER BY report_date) AS cum_claims,\n  ROUND(SUM(inc) OVER (ORDER BY report_date), 2) AS cum_incurred\nFROM d ORDER BY report_date;","explanation":"Aggregate-then-window avoids RANGE tie surprises.","ordered":true,"similar":null,"columns":["report_date","cum_claims","cum_incurred"],"expected":["2024-05-02␟1.00␟1500.00","2024-05-03␟2.00␟3000.00","2024-09-02␟3.00␟7024.57","2025-04-18␟4.00␟14766.58","2025-04-25␟5.00␟17589.77","2025-06-02␟6.00␟20690.82","2025-08-22␟7.00␟21599.94","2025-09-01␟8.00␟33570.57","2025-09-12␟9.00␟36574.35","2025-09-13␟10.00␟44767.03","2025-09-14␟11.00␟57428.60","2025-09-23␟12.00␟63520.04","2025-11-01␟13.00␟64182.71","2025-11-24␟14.00␟72163.61","2025-12-12␟15.00␟79956.64","2026-01-21␟16.00␟86107.20","2026-04-25␟17.00␟98162.22","2026-05-07␟18.00␟102346.64","2026-07-02␟19.00␟115979.34","2026-07-07␟20.00␟128405.64","2026-07-16␟21.00␟128641.66","2027-04-17␟22.00␟135274.50","2027-06-05␟23.00␟146812.37","2027-11-06␟24.00␟150523.38"],"tables":["claims"]},{"id":"q52","tier":"hard","topic":"top-n","title":"Top cause per state","prompt":"Tables: claims, policies. For each policy state, return the cause with the highest total incurred (ties: alphabetical) as state, cause, inc (2 decimals). Order by state.","hint":"Aggregate, then DISTINCT ON (state) ORDER BY state, inc DESC, cause.","solution":"SELECT DISTINCT ON (p.state) p.state, c.cause,\n  ROUND(SUM(c.paid_amount + c.reserve_amount), 2) AS inc\nFROM claims c JOIN policies p ON p.policy_id = c.policy_id\nGROUP BY p.state, c.cause\nORDER BY p.state, SUM(c.paid_amount + c.reserve_amount) DESC, c.cause;","explanation":"DISTINCT ON works after GROUP BY: one row per state, chosen by the ORDER BY.","ordered":true,"similar":null,"columns":["state","cause","inc"],"expected":["CA␟Fire␟15071.68","FL␟Theft␟13833.45","NY␟Injury␟13632.70","TX␟Water␟12426.30"],"tables":["claims","policies"]},{"id":"q53","tier":"hard","topic":"self-join","title":"Overlapping terms","prompt":"From policies, return pairs (customer_id, p1, p2) of policies of the same customer and product whose terms overlap, with p1 < p2. Order by all columns.","hint":"a.effective_date < b.expiration_date AND b.effective_date < a.expiration_date.","solution":"SELECT a.customer_id, a.policy_id AS p1, b.policy_id AS p2\nFROM policies a\nJOIN policies b ON a.customer_id = b.customer_id AND a.product = b.product\n  AND a.policy_id < b.policy_id\n  AND a.effective_date < b.expiration_date AND b.effective_date < a.expiration_date\nORDER BY 1, 2, 3;","explanation":"Overlap check is a good dbt singular test. Postgres alternative: daterange(a...) && daterange(b...).","ordered":true,"similar":null,"columns":["customer_id","p1","p2"],"expected":["4.00␟106.00␟107.00"],"tables":["policies"]},{"id":"q54","tier":"hard","topic":"dedup","title":"Near-duplicate claims","prompt":"From claims, return pairs c1 < c2 with policy_id where both claims are on the same policy, same cause, and loss dates within 3 days. Order by c1, c2.","hint":"Self join; ABS(a.loss_date - b.loss_date) <= 3.","solution":"SELECT a.claim_id AS c1, b.claim_id AS c2, a.policy_id\nFROM claims a\nJOIN claims b ON a.policy_id = b.policy_id AND a.cause = b.cause\n  AND a.claim_id < b.claim_id\n  AND ABS(a.loss_date - b.loss_date) <= 3\nORDER BY 1, 2;","explanation":"Fuzzy dedup is also a fraud signal.","ordered":true,"similar":{"url":"https://leetcode.com/problems/duplicate-emails/","title":"LeetCode: Duplicate Emails"},"columns":["c1","c2","policy_id"],"expected":["23.00␟24.00␟101.00"],"tables":["claims"]},{"id":"q55","tier":"hard","topic":"window","title":"Gap between terms","prompt":"From policies, for each customer's consecutive policies (by effective_date, policy_id) return customer_id, policy_id and gap_days = effective_date minus the previous policy's expiration_date (negative = overlap). Skip each customer's first policy.","hint":"LAG(expiration_date) OVER (...).","solution":"WITH x AS (\n  SELECT customer_id, policy_id, effective_date,\n    LAG(expiration_date) OVER (PARTITION BY customer_id ORDER BY effective_date, policy_id) AS prev_exp\n  FROM policies)\nSELECT customer_id, policy_id, effective_date - prev_exp AS gap_days\nFROM x WHERE prev_exp IS NOT NULL\nORDER BY customer_id, policy_id;","explanation":"Lapse analysis for retention.","ordered":true,"similar":null,"columns":["customer_id","policy_id","gap_days"],"expected":["3.00␟104.00␟0.00","4.00␟106.00␟45.00","4.00␟107.00␟-45.00","5.00␟109.00␟0.00","7.00␟112.00␟0.00","8.00␟114.00␟0.00","8.00␟115.00␟45.00","9.00␟117.00␟0.00","10.00␟119.00␟45.00","11.00␟121.00␟45.00","11.00␟122.00␟0.00"],"tables":["policies"]},{"id":"q56","tier":"hard","topic":"cohort","title":"Bind within 30 days of signup","prompt":"Tables: customers, quotes. Per signup year (yr), return customers and pct = % of those customers with a bound quote dated 0-30 days after signup (1 decimal). Order by yr.","hint":"Put the date and bound conditions in the LEFT JOIN's ON clause; COUNT DISTINCT both sides.","solution":"SELECT EXTRACT(YEAR FROM c.signup_date)::int AS yr,\n  COUNT(DISTINCT c.customer_id) AS customers,\n  ROUND(100.0 * COUNT(DISTINCT q.customer_id) / COUNT(DISTINCT c.customer_id), 1) AS pct\nFROM customers c\nLEFT JOIN quotes q ON q.customer_id = c.customer_id AND q.bound\n  AND q.quote_date - c.signup_date BETWEEN 0 AND 30\nGROUP BY 1 ORDER BY 1;","explanation":"Conditions in ON keep the denominator intact.","ordered":true,"similar":null,"columns":["yr","customers","pct"],"expected":["2024.00␟9.00␟0.00","2025.00␟3.00␟0.00"],"tables":["customers","quotes"]},{"id":"q57","tier":"hard","topic":"window","title":"Median order by country","prompt":"Tables: orders, users. Return country and median = median amount of complete orders by the user's country (2 decimals). Order by country.","hint":"PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY amount).","solution":"SELECT u.country,\n  ROUND((PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY o.amount))::numeric, 2) AS median\nFROM orders o JOIN users u ON u.user_id = o.user_id\nWHERE o.status = 'complete'\nGROUP BY u.country\nORDER BY u.country;","explanation":"Postgres has ordered-set aggregates (PERCENTILE_CONT/DISC, MODE). Databricks: median()/percentile_approx.","ordered":true,"similar":null,"columns":["country","median"],"expected":["CA␟303.40","DE␟401.00","UK␟303.71","US␟281.53"],"tables":["orders","users"]},{"id":"q58","tier":"hard","topic":"window","title":"Salary vs department","prompt":"From employees, return name, dept, salary, vs_avg = salary minus dept average (0 decimals) and gap_to_next = next higher salary in the dept minus this salary (NULL for the top). Order by dept, salary desc.","hint":"AVG() OVER (PARTITION BY dept) and LAG(salary) OVER (PARTITION BY dept ORDER BY salary DESC, emp_id).","solution":"SELECT name, dept, salary,\n  ROUND(salary - AVG(salary) OVER (PARTITION BY dept)) AS vs_avg,\n  LAG(salary) OVER (PARTITION BY dept ORDER BY salary DESC, emp_id) - salary AS gap_to_next\nFROM employees\nORDER BY dept, salary DESC;","explanation":"Multiple windows in one SELECT; name a shared one with WINDOW w AS (...).","ordered":true,"similar":null,"columns":["name","dept","salary","vs_avg","gap_to_next"],"expected":["Raj␟Data␟190000.00␟35000.00␟NULL","Zoe␟Data␟160000.00␟5000.00␟30000.00","Uma␟Data␟155000.00␟0.00␟5000.00","Tess␟Data␟150000.00␟-5000.00␟5000.00","Vic␟Data␟120000.00␟-35000.00␟30000.00","Sol␟Eng␟200000.00␟33000.00␟NULL","Xia␟Eng␟170000.00␟3000.00␟30000.00","Ari␟Eng␟170000.00␟3000.00␟0.00","Wes␟Eng␟165000.00␟-2000.00␟5000.00","Yuri␟Eng␟130000.00␟-37000.00␟35000.00","Mira␟Exec␟250000.00␟0.00␟NULL"],"tables":["employees"]},{"id":"q59","tier":"hard","topic":"pivot","title":"Report-lag triangle","prompt":"From claims, return ay (accident year = year of loss_date) and claim counts by report lag bucket: d0_1 (0-1 days), d2_7, d8_30, d31p (31+). Order by ay.","hint":"Compute lag = report_date - loss_date in a subquery, then COUNT(*) FILTER per bucket.","solution":"SELECT EXTRACT(YEAR FROM loss_date)::int AS ay,\n  COUNT(*) FILTER (WHERE lag <= 1) AS d0_1,\n  COUNT(*) FILTER (WHERE lag BETWEEN 2 AND 7) AS d2_7,\n  COUNT(*) FILTER (WHERE lag BETWEEN 8 AND 30) AS d8_30,\n  COUNT(*) FILTER (WHERE lag > 30) AS d31p\nFROM (SELECT loss_date, report_date - loss_date AS lag FROM claims) x\nGROUP BY 1 ORDER BY 1;","explanation":"Report-lag shapes inform IBNR.","ordered":true,"similar":null,"columns":["ay","d0_1","d2_7","d8_30","d31p"],"expected":["2024.00␟3.00␟0.00␟0.00␟0.00","2025.00␟1.00␟5.00␟4.00␟2.00","2026.00␟2.00␟2.00␟2.00␟0.00","2027.00␟0.00␟3.00␟0.00␟0.00"],"tables":["claims"]},{"id":"q60","tier":"hard","topic":"having","title":"All claims closed","prompt":"Tables: claims, policies. Return customer_id of customers with at least one claim where every claim is CLOSED. Order by customer_id.","hint":"HAVING BOOL_AND(status = 'CLOSED').","solution":"SELECT p.customer_id\nFROM claims c JOIN policies p ON p.policy_id = c.policy_id\nGROUP BY p.customer_id\nHAVING BOOL_AND(c.status = 'CLOSED')\nORDER BY p.customer_id;","explanation":"'For all' questions: BOOL_AND in Postgres, or COUNT of violations = 0.","ordered":true,"similar":{"url":"https://leetcode.com/problems/customers-who-bought-all-products/","title":"LeetCode: Customers Who Bought All Products"},"columns":["customer_id"],"expected":["12.00"],"tables":["claims","policies"]},{"id":"q61","tier":"hard","topic":"sessionize","title":"Order sessions","prompt":"From orders, group each user's orders into sessions: a new session starts when more than 30 days passed since the user's previous order (or it's the first). Return user_id, sessions. Order by user_id.","hint":"LAG(order_date), flag new sessions, then SUM the flags.","solution":"WITH x AS (\n  SELECT user_id,\n    CASE WHEN order_date - LAG(order_date) OVER (PARTITION BY user_id ORDER BY order_date, order_id) <= 30\n         THEN 0 ELSE 1 END AS new_s\n  FROM orders)\nSELECT user_id, SUM(new_s) AS sessions\nFROM x GROUP BY user_id ORDER BY user_id;","explanation":"Sessionization = gaps-and-islands with a threshold. The NULL from the first LAG falls to ELSE 1.","ordered":true,"similar":null,"columns":["user_id","sessions"],"expected":["1.00␟3.00","2.00␟5.00","3.00␟1.00","4.00␟2.00","5.00␟3.00","6.00␟1.00","7.00␟4.00","8.00␟2.00","9.00␟2.00","11.00␟3.00","12.00␟2.00"],"tables":["orders"]},{"id":"q62","tier":"hard","topic":"window","title":"First and last premium","prompt":"From policies, per customer return customer_id, first_prem (earliest term's premium), last_prem (latest term's premium) and terms. Order by customer_id.","hint":"FIRST_VALUE / LAST_VALUE need a full frame, or use DISTINCT ON twice.","solution":"SELECT DISTINCT customer_id,\n  FIRST_VALUE(premium) OVER w AS first_prem,\n  LAST_VALUE(premium) OVER w AS last_prem,\n  COUNT(*) OVER (PARTITION BY customer_id) AS terms\nFROM policies\nWINDOW w AS (PARTITION BY customer_id ORDER BY effective_date, policy_id\n  ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING)\nORDER BY customer_id;","explanation":"LAST_VALUE with the default frame returns the current row: the #1 window gotcha.","ordered":true,"similar":{"url":"https://leetcode.com/problems/game-play-analysis-i/","title":"LeetCode: Game Play Analysis I"},"columns":["customer_id","first_prem","last_prem","terms"],"expected":["1.00␟3341.66␟3341.66␟1.00","2.00␟1093.50␟1093.50␟1.00","3.00␟852.25␟947.39␟2.00","4.00␟858.50␟1274.65␟3.00","5.00␟1117.10␟4009.08␟2.00","6.00␟2649.89␟2649.89␟1.00","7.00␟2420.34␟1109.47␟2.00","8.00␟1678.25␟1418.39␟3.00","9.00␟903.50␟1617.47␟2.00","10.00␟946.72␟734.56␟2.00","11.00␟2364.91␟3366.46␟3.00","12.00␟1345.81␟1345.81␟1.00"],"tables":["policies"]},{"id":"q63","tier":"hard","topic":"joins","title":"Quoted, never bound","prompt":"Tables: customers, quotes, policies. Return names of customers with 2+ quotes, none bound, and no policies. Order by name. (An empty result can be correct; check why.)","hint":"GROUP BY + HAVING NOT BOOL_OR(bound) + NOT EXISTS policies.","solution":"SELECT c.name\nFROM customers c JOIN quotes q ON q.customer_id = c.customer_id\nWHERE NOT EXISTS (SELECT 1 FROM policies p WHERE p.customer_id = c.customer_id)\nGROUP BY c.customer_id, c.name\nHAVING COUNT(*) >= 2 AND NOT BOOL_OR(q.bound)\nORDER BY c.name;","explanation":"An empty result is a valid answer here: every customer in the seed has a policy.","ordered":true,"similar":null,"columns":["name"],"expected":[],"tables":["customers","policies","quotes"]},{"id":"q64","tier":"hard","topic":"dates","title":"Daily and 7-day active users","prompt":"From logins, for each distinct login_date return dau (distinct users that day) and wau7 (distinct users in the 7 days ending that day). Order by login_date.","hint":"Self join on l.login_date BETWEEN d.login_date - 6 AND d.login_date; COUNT(DISTINCT) FILTER for dau.","solution":"WITH d AS (SELECT DISTINCT login_date FROM logins)\nSELECT d.login_date,\n  COUNT(DISTINCT l.user_id) FILTER (WHERE l.login_date = d.login_date) AS dau,\n  COUNT(DISTINCT l.user_id) AS wau7\nFROM d JOIN logins l ON l.login_date BETWEEN d.login_date - 6 AND d.login_date\nGROUP BY d.login_date\nORDER BY d.login_date;","explanation":"COUNT(DISTINCT) is not allowed as a window function in Postgres; use a range self join.","ordered":true,"similar":{"url":"https://leetcode.com/problems/user-activity-for-the-past-30-days-i/","title":"LeetCode: User Activity for the Past 30 Days I"},"columns":["login_date","dau","wau7"],"expected":["2025-06-02␟7.00␟7.00","2025-06-03␟3.00␟8.00","2025-06-04␟4.00␟8.00","2025-06-05␟2.00␟8.00","2025-06-06␟1.00␟8.00","2025-06-07␟2.00␟8.00","2025-06-08␟3.00␟8.00","2025-06-09␟4.00␟8.00","2025-06-10␟5.00␟8.00","2025-06-11␟4.00␟8.00","2025-06-12␟4.00␟7.00","2025-06-13␟2.00␟7.00","2025-06-14␟2.00␟7.00","2025-06-15␟3.00␟7.00","2025-06-16␟1.00␟7.00","2025-06-21␟1.00␟3.00"],"tables":["logins"]}];
